const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.bag}</svg>`;
const money=value=>Number(value||0).toLocaleString('zh-CN',{maximumFractionDigits:2});
const defaults=()=>({query:'',category:'all',campus:'',condition:'',serviceDirection:'',serviceMode:'',cheap:false,fresh:false,graduation:false,sort:'newest'});
const state={contactExchange:null,exchangeError:'',exchangeOpen:false,conversations:[],activeConversation:null,conversationProduct:null,dismissedProductCardId:null,messages:[],messageError:'',session:null,sessionError:'',filters:defaults(),home:{items:[],total:0,realTotal:0,demoTotal:0,counts:{},page:0,hasMore:false,loading:false,error:''},published:[],favorites:[],favoriteIds:new Set(),favoritesError:'',detail:null,draft:null,profileError:'',tab:'published',managementStatus:'all'};
let exchangeVersion=0,exchangeSaving=false,exchangeReadInFlight=false,messageSaving=false,settingsSaving=false,routeVersion=0,toastTimer,modalFocus,currentRoute='',homeRequest=0,modalVersion=0,submitting=false,uploading=false,signingOut=false,emailAttempt=0,loginTicker,messageTicker,identityVersion=0,profileSaving=false;
const pendingFavorite=new Set(),statusBusy=new Set(),app=$('#app');
function routeInfo(){const[path,search='']=(location.hash.slice(1)||'/').split('?');return{path,params:new URLSearchParams(search)};}
function decodeId(value){try{return decodeURIComponent(value);}catch{return '';}}
function navigate(route){if(submitting||uploading){toast('正在保存或处理照片，请稍等一下。');return;}closeModal();if(location.hash===`#${route}`)loadRoute();else location.hash=route;}
function signedIn(){return !state.identityUnconfirmed&&((state.session?.authentication?.provider==='school_email'&&state.session?.user?.emailVerified===true)||(state.session?.development===true&&state.session?.authentication?.provider==='local_preview'&&state.session?.user?.preview===true));}
function safeReturnTo(value='/#/') {
  if(typeof value!=='string'||!value.startsWith('/')||value.startsWith('//')||/[\\\u0000-\u001f\u007f]/.test(value))return '/#/';
  let url;try{url=new URL(value,location.origin);}catch{return '/#/';}
  if(url.origin!==location.origin||url.pathname!=='/'||url.search)return '/#/';
  if(!url.hash)return '/#/';
  const path=url.hash.slice(1).split('?')[0];
  if(!['/','/publish','/profile','/settings','/messages'].includes(path)&&!/^\/(?:product|messages)\/[A-Za-z0-9_-]+$/.test(path))return '/#/';
  return `/${url.hash}`;
}
function currentReturnTo(){const{path,params}=routeInfo();return safeReturnTo(path==='/login'?params.get('return_to'):`/${location.hash||'#/'}`);}
function loginPath(returnTo=currentReturnTo()){return `#/login?return_to=${encodeURIComponent(safeReturnTo(returnTo))}`;}
function authentication(){return{provider:signedIn()?state.session.authentication.provider:'guest',configured:state.session?.authentication?.email?.configured===true};}
function accountLabel(){return signedIn()?(state.session.user.preview?'本地体验账号':'学校邮箱账号'):'访客';}
function loginLink(label='学校邮箱 / 访客登录',returnTo=currentReturnTo()){return `<a class="button primary" href="${esc(loginPath(returnTo))}">${icon('user')}${esc(label)}${icon('arrow')}</a>`;}
function developmentNotice(){return state.session?.development?'<div class="development-notice" role="status">本地开发预览 · 数据仅保存在本地预览存储，不会同步到正式站点。可使用本地体验账号查看登录后的界面。</div>':'';}
function draftSnapshot(d){return JSON.stringify({fields:d.fields,specs:d.specs,images:d.images.map(p=>p.mediaId||p.url),consent:d.consent});}
function hasUnsavedDraft(){return Boolean(state.draft&&draftSnapshot(state.draft)!==state.draft.initialSnapshot);}
function identitySnapshot(){return{id:state.session?.user?.id,version:identityVersion};}
function sameIdentity(snapshot){return signedIn()&&snapshot.id===state.session.user.id&&snapshot.version===identityVersion;}
function authExpired(error,render=true){
  if(error?.status!==401)return false;
  const prior=state.session?.user?.id||state.emailLogin.priorUserId;if(prior){state.emailLogin.priorUserId=prior;state.expiredUserId=prior;}
  clearPersonalState(false);state.identityUnconfirmed=false;state.session={...state.session,user:null,authentication:{...state.session?.authentication,provider:'guest'}};closeModal();
  if(state.draft){state.draft.error='登录已失效，请重新使用学校邮箱登录。';state.draft.notice='当前草稿已保留；同一账号登录后可继续，切换账号会清除旧草稿。';}
  if(render){loadRoute();toast('登录已失效，请重新使用学校邮箱登录。');}return true;
}
function blankEmailLogin(){return{email:'',code:'',challengeId:'',challengeEmail:'',requestEmail:'',emailMasked:'',expiresAt:0,retryAt:0,retryEmail:'',sending:false,verifying:false,verifiedPending:false,priorUserId:null,returnTo:'/#/',error:'',notice:''};}
state.emailLogin=blankEmailLogin();state.guestError='';
function normalizeSchoolEmail(value){return String(value||'').trim().toLowerCase();}
function validSchoolEmail(value){const email=normalizeSchoolEmail(value),parts=email.split('@');return parts.length===2&&parts[1]==='student.xjtlu.edu.cn'&&parts[0].length>=1&&parts[0].length<=64&&/^[a-z0-9_%+-]+(?:\.[a-z0-9_%+-]+)*$/.test(parts[0]);}
function retrySeconds(){const e=state.emailLogin;return e.retryEmail===normalizeSchoolEmail(e.email)?Math.max(0,Math.ceil((e.retryAt-Date.now())/1000)):0;}
function challengeActive(){const e=state.emailLogin;return Boolean(e.challengeId&&e.challengeEmail===normalizeSchoolEmail(e.email)&&e.expiresAt>Date.now());}
function clearChallenge(){const e=state.emailLogin;Object.assign(e,{code:'',challengeId:'',challengeEmail:'',emailMasked:'',expiresAt:0,verifiedPending:false,notice:''});}
function setLoginEmail(value){const e=state.emailLogin,normalized=normalizeSchoolEmail(value),bound=e.challengeEmail||e.requestEmail;e.email=value;if(bound&&normalized!==bound){emailAttempt++;clearChallenge();Object.assign(e,{retryAt:0,retryEmail:'',requestEmail:'',error:''});}refreshLoginControls();}
function stopLoginTimer(){if(loginTicker){clearInterval(loginTicker);loginTicker=null;}}
function startLoginTimer(){stopLoginTimer();if(routeInfo().path==='/login')loginTicker=setInterval(()=>{if(routeInfo().path!=='/login')stopLoginTimer();else refreshLoginControls();},1000);}
function refreshLoginControls(){
  if(routeInfo().path!=='/login')return;const e=state.emailLogin,seconds=retrySeconds(),configured=authentication().configured;
  const send=$('#send-email-button');if(send){send.disabled=!configured||e.sending||e.verifying||signingOut||seconds>0;send.textContent=e.sending?'正在发送…':seconds>0?`${seconds} 秒后重发`:e.challengeId?'重新发送验证码':'发送验证码';}
  const verify=$('#verify-email-button');if(verify){verify.disabled=!configured||e.sending||e.verifying||signingOut||(!e.verifiedPending&&(!challengeActive()||!/^\d{6}$/.test(e.code)));verify.textContent=e.verifying?'正在确认登录…':e.verifiedPending?'重新确认登录状态':'验证并登录';}
  const email=$('#school-email');if(email)email.disabled=e.verifying||signingOut;
  const code=$('#school-code');if(code){code.disabled=!challengeActive()||e.sending||e.verifying||e.verifiedPending||signingOut;if(code.value!==e.code)code.value=e.code;}
  const feedback=$('#email-feedback');if(feedback)feedback.innerHTML=`${e.error?`<p class="email-error" role="alert">${esc(e.error)}</p>`:''}${e.notice?`<p class="email-success" role="status">${esc(e.notice)}</p>`:''}`;
  const deadline=$('#code-deadline');if(deadline){const remaining=Math.max(0,Math.ceil((e.expiresAt-Date.now())/1000));deadline.textContent=e.challengeId?(remaining>0?`验证码剩余 ${Math.floor(remaining/60)} 分 ${remaining%60} 秒，最多尝试 5 次。`:'验证码已过期，请重新发送。'):'验证码有效期为 10 分钟，最多尝试 5 次；达到上限需重新发送。';}
  const guest=$('[data-action="guest"]');if(guest)guest.disabled=e.verifying||signingOut;
}
function renderLogin(){if(routeInfo().path==='/login'){shell(loginPage(routeInfo().params));refreshLoginControls();startLoginTimer();}}
function loginPage(params){
  const returnTo=safeReturnTo(params.get('return_to')||'/#/'),e=state.emailLogin,configured=authentication().configured;
  return `<section class="login-page school-login-page"><div class="login-intro"><span class="eyebrow">A LITTLE HELLO, A NEW STORY</span><h1>欢迎回来，橘子同学 <span>🍊</span></h1><p>用学校邮箱验证登录，或以访客身份先逛逛。</p></div>
    ${hasUnsavedDraft()?`<div class="login-draft-warning"><strong>你的发布草稿仍留在当前页面</strong><p>学校邮箱验证不会刷新页面。同一账号登录可继续编辑；若切换其他账号或进入访客模式，旧账号草稿会被清除。</p><a class="text-button" href="${esc(returnTo.slice(1))}">返回原页面 ${icon('arrow')}</a></div>`:''}
    ${signedIn()?`<div class="login-current-account"><span class="profile-avatar">🍊</span><div><strong>${esc(accountLabel())}</strong><p>${state.session.user.preview?'模拟登录 · 不代表学校邮箱已验证':`${esc(state.session.user.emailMasked||'学校邮箱账号')} · 未核验在读学籍`}</p></div><a class="button secondary small" href="${esc(returnTo.slice(1))}">返回继续</a><button class="text-button" data-action="logout">退出登录</button></div>`:''}
    <div class="school-login-layout"><section class="login-panel email-login-panel"><div class="login-panel-heading"><h2>学校邮箱验证码</h2><span class="badge ${configured?'mint':''}">${configured?'邮箱验证':'邮件服务未开通'}</span></div><p class="email-panel-copy">仅限 <strong>@student.xjtlu.edu.cn</strong> 学生邮箱。每次验证成功后，公开昵称自动设为邮箱前缀并去除数字，最长 20 个字符。</p>
    ${!configured?'<div class="email-unavailable" role="status">验证码邮件服务尚未开通，暂不能发送。你仍可填写邮箱，或先以访客身份浏览。</div>':''}
    <form id="school-login-form"><div class="form-field"><label for="school-email">学校邮箱</label><input id="school-email" name="email" type="email" required maxlength="254" value="${esc(e.email)}" placeholder="Example.Student23@student.xjtlu.edu.cn" autocomplete="email" autocapitalize="none" spellcheck="false" inputmode="email"><span class="field-hint">请使用你能够接收邮件的学校邮箱。</span></div><button id="send-email-button" class="button secondary email-send-button" type="button" data-action="send-email" ${!configured?'disabled':''}>发送验证码</button><div class="form-field"><label for="school-code">6 位验证码</label><input id="school-code" name="code" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" value="${esc(e.code)}" placeholder="输入邮件中的 6 位数字" aria-describedby="code-deadline" required ${!challengeActive()?'disabled':''}><p id="code-deadline" class="field-hint">验证码有效期为 10 分钟，最多尝试 5 次；达到上限需重新发送。</p></div><div id="email-feedback" aria-live="polite"></div><button id="verify-email-button" class="button primary" type="submit" disabled>验证并登录</button></form></section>
    <section class="login-panel guest-login-panel"><span class="guest-illustration" aria-hidden="true">🌿</span><h2>访客登录</h2><p>不用填写资料，先发现校园里的好物。</p><ul><li>浏览公开商品与照片</li><li>使用搜索与筛选</li><li>发布、收藏、站内私信需邮箱验证登录</li></ul>${signedIn()?'<p class="guest-account-note">以访客进入会退出当前学校邮箱账号。</p>':''}${state.guestError?`<p class="email-error" role="alert">${esc(state.guestError)}</p>`:''}<button class="button secondary" data-action="guest">以访客身份浏览 ${icon('arrow')}</button></section></div>
    ${state.session?.authentication?.preview?.enabled?'<section class="login-panel local-preview-panel"><h2>本地页面体验</h2><p>无需收验证码，即可查看「我的」和编辑个人资料。这里使用独立的本地模拟账号，数据不会同步线上，也不代表学校邮箱已验证。</p><button class="button primary" type="button" data-action="local-preview">进入本地体验账号</button></section>':''}
    <p class="login-identity-note">${icon('shield')}学校邮箱验证只确认邮箱控制权，不等于在读学籍认证。</p></section>`;
}
async function localPreviewLogin(){
  if(!state.session?.authentication?.preview?.enabled)return;
  const returnTo=currentReturnTo(),prior=state.session?.user?.id;
  try{
    const result=await api.preview();if(result.ok!==true)throw new Error('本地体验账号尚未准备好。');
    const session=await api.session();if(session.development!==true||session.authentication?.provider!=='local_preview'||session.user?.preview!==true)throw new Error('未能确认本地体验登录状态。');
    clearPersonalState(Boolean(prior&&prior!==session.user.id));state.session=session;state.sessionError='';state.identityUnconfirmed=false;
    navigate(safeReturnTo(returnTo).slice(2));toast('已进入本地体验账号。');
  }catch(error){toast(message(error));}
}
async function sendEmailCode(){
  const e=state.emailLogin;if(e.sending||e.verifying||signingOut)return;
  const input=String($('#school-email')?.value??e.email).trim(),email=normalizeSchoolEmail(input);e.email=input;e.error='';e.notice='';
  if(!validSchoolEmail(email)){e.error='请填写有效的 @student.xjtlu.edu.cn 学校邮箱；邮箱名称不能以点开头、结尾或包含连续点。';refreshLoginControls();return;}
  if(!authentication().configured){e.error='验证码邮件服务尚未开通，暂不能发送。请先以访客身份浏览。';refreshLoginControls();return;}
  if(retrySeconds()>0){refreshLoginControls();return;}
  const token=++emailAttempt;e.sending=true;e.requestEmail=email;refreshLoginControls();
  try{
    const result=await api.sendEmail(email);
    if(token!==emailAttempt||normalizeSchoolEmail(e.email)!==email)return;
    if(typeof result.challengeId!=='string'||!result.challengeId||!Number.isFinite(result.expiresIn)||result.expiresIn<=0||!Number.isFinite(result.retryAfter)||result.retryAfter<0||typeof result.emailMasked!=='string')throw new Error('未能确认验证码发送结果，请稍后重试。');
    Object.assign(e,{challengeId:result.challengeId,challengeEmail:email,code:'',emailMasked:result.emailMasked,expiresAt:Date.now()+Math.min(result.expiresIn,600)*1000,retryAt:Date.now()+result.retryAfter*1000,retryEmail:email,verifiedPending:false,notice:`验证码已发送至 ${result.emailMasked}，请查收邮件。`});
  }catch(error){if(token===emailAttempt){e.error=message(error);if(error.status===429&&error.retryAfter>0){e.retryAt=Date.now()+error.retryAfter*1000;e.retryEmail=email;}}}
  finally{if(e===state.emailLogin)e.sending=false;renderLogin();}
}
function clearPersonalState(clearDraft=false){state.contactExchange=null;state.exchangeError='';state.exchangeOpen=false;state.conversations=[];state.activeConversation=null;state.conversationProduct=null;state.dismissedProductCardId=null;state.messages=[];exchangeVersion++;identityVersion++;routeVersion++;homeRequest++;pendingFavorite.clear();statusBusy.clear();state.published=[];state.favorites=[];state.favoriteIds=new Set();state.favoritesError='';state.profileError='';state.detail=null;state.home.items=[];state.home.page=0;if(clearDraft&&state.draft){revokeDraft(state.draft);state.draft=null;}}
async function finishEmailLogin(){
  const e=state.emailLogin,session=await api.session();
  if(session.authentication?.provider!=='school_email'||session.user?.emailVerified!==true)throw new Error('验证码已验证，但尚未确认登录状态，请点击“重新确认登录状态”。');
  const changed=Boolean(e.priorUserId&&e.priorUserId!==session.user.id),returnTo=e.returnTo;
  clearPersonalState(changed);state.session=session;state.sessionError='';state.identityUnconfirmed=false;state.expiredUserId=null;if(state.draft)state.draft.ownerId=session.user.id;
  try{const result=await api.favorites();state.favorites=result.items;state.favoriteIds=new Set(result.items.map(p=>p.id));}catch(error){state.favoritesError=message(error);}
  emailAttempt++;state.emailLogin=blankEmailLogin();stopLoginTimer();toast(changed?'学校邮箱登录成功，已清除旧账号的草稿。':'学校邮箱登录成功。');navigate(safeReturnTo(returnTo).slice(2));
}
async function verifyEmailCode(){
  const e=state.emailLogin;if(e.sending||e.verifying||signingOut)return;e.error='';
  if(!e.verifiedPending&&(!challengeActive()||!/^\d{6}$/.test(e.code))){e.error='请先发送验证码，并填写有效期内的 6 位数字验证码。';refreshLoginControls();return;}
  e.verifying=true;refreshLoginControls();
  try{
    if(!e.verifiedPending){e.priorUserId=state.identityUnconfirmed?e.priorUserId:signedIn()?state.session.user.id:e.priorUserId||state.draft?.ownerId||null;e.returnTo=currentReturnTo();const result=await api.verifyEmail({email:e.email.trim(),challengeId:e.challengeId,code:e.code});if(result.ok!==true)throw new Error('服务器未确认验证码验证成功，请重试。');e.verifiedPending=true;state.identityUnconfirmed=true;e.code='';}
    await finishEmailLogin();
  }catch(error){if(e===state.emailLogin){e.error=message(error);e.code='';if(['CODE_EXPIRED','CODE_ATTEMPTS_EXCEEDED'].includes(error.code)){clearChallenge();e.error=message(error);}if(error.status===429&&error.retryAfter>0){e.retryAt=Date.now()+error.retryAfter*1000;e.retryEmail=normalizeSchoolEmail(e.email);}}}
  finally{if(e===state.emailLogin)e.verifying=false;renderLogin();}
}
function confirmLogout(){const en=state.session?.user?.language==='en';showModal(`<span class="modal-emoji">🌿</span><h2>${en?'Log out of this account?':'要退出当前账号吗？'}</h2><p>${en?'After logging out, you can browse as a guest. Posting, favorites and seller contacts require school email verification.':'退出后将以访客身份浏览，发布、收藏与联系方式需要学校邮箱验证登录。'}</p>${hasUnsavedDraft()?`<p class="logout-draft-warning">${en?'Logging out clears your unsaved listing form and photos.':'退出会清除当前未保存的表单和照片，请先保留内容。'}</p>`:''}<div class="modal-actions"><button class="button secondary" data-action="close-modal">${en?'Keep browsing':'继续逛逛'}</button><button class="button primary" data-action="confirm-logout">${en?'Log out':'确认退出'}</button></div>`,'确认退出登录');}
async function becomeGuest(kind='guest',confirmed=false){
  if(signingOut||state.emailLogin.verifying)return;
  if(kind==='guest'&&hasUnsavedDraft()&&!confirmed){showModal('<span class="modal-emoji">🌿</span><h2>以访客身份继续吗？</h2><p>这会退出当前账号，并清除未保存的表单和照片。已发布的商品与收藏仍保留在原账号。</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">返回保留内容</button><button class="button primary" data-action="confirm-guest">清除草稿，进入访客</button></div>','确认访客浏览');return;}
  signingOut=true;state.guestError='';refreshLoginControls();let cleared=false;
  try{
    const result=await(kind==='logout'?api.logout():api.guest());if(result.ok!==true)throw new Error('服务器未确认会话已清除，请重新尝试。');cleared=true;
    const session=await api.session();if(session.user!==null||session.authentication?.provider!=='guest')throw new Error('尚未确认访客状态，请重新尝试。');
    clearPersonalState(true);state.session=session;state.sessionError='';state.identityUnconfirmed=false;state.expiredUserId=null;emailAttempt++;state.emailLogin=blankEmailLogin();stopLoginTimer();closeModal();signingOut=false;navigate('/');toast(kind==='logout'?'已退出，正在以访客身份浏览。':'正在以访客身份浏览。');
  }catch(error){
    if(cleared){clearPersonalState(true);state.session=null;state.sessionError='会话清除后暂时无法确认登录状态，请重新加载。';closeModal();shell(errorView(state.sessionError,'retry-session'));}
    else if(kind==='logout')showModal(`<h2>尚未完成退出</h2><p role="alert">${esc(message(error))}</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">返回</button><button class="button primary" data-action="confirm-logout">重试退出</button></div>`,'退出未完成');
    else{state.guestError=message(error);closeModal();renderLogin();}
  }finally{signingOut=false;refreshLoginControls();}
}
async function logout(){return becomeGuest('logout',true);}
function toast(copy){const target=$('#toast');target.textContent=copy;target.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>target.classList.remove('visible'),3600);}
function message(error){return error?.message||'暂时没有完成，请稍后重试。';}
function timeAgo(value){const date=typeof value==='number'?value:Date.parse(value);if(!Number.isFinite(date))return'最近发布';const hours=Math.max(0,Math.floor((Date.now()-date)/3600000));return hours<1?'刚刚发布':hours<24?`${hours} 小时前`:hours<48?'昨天发布':`${Math.floor(hours/24)} 天前`;}
function categoryName(id){return categories.find(c=>c.id===id)?.name||'生活用品';}
const demoImages=new Set(['fan','lamp','kettle','hairdryer','speaker','headphones','scooter-1','scooter-2','scooter-3','scooter-4','scooter-5','scooter-6','chair','mug','umbrella','plant','yoga'].map(name=>`/assets/${name}.jpg`));
function imageUrl(value,isDemo=false){return typeof value==='string'&&(value.startsWith('/api/media/')||(isDemo===true&&demoImages.has(value)))?value:'';}
function productImage(p,index=0){return imageUrl(p.images?.[index],p.isDemo);}
function photoMarkup(p,className='card-image'){const src=productImage(p);return src?`<img class="${className}" src="${esc(src)}" alt="${esc(p.title)}" loading="lazy">`:`<div class="missing-photo" role="img" aria-label="商品照片暂不可用">${icon('bag')}<span>照片暂不可用</span></div>`;}
function empty(title,copy,action=''){return`<div class="empty-state"><span class="empty-emoji">🍊</span><h2>${title}</h2><p>${copy}</p>${action}</div>`;}
function loading(copy='好物正在集合…'){return`<div class="loading-state" role="status"><span class="loading-spinner" aria-hidden="true"></span><p>${copy}</p></div>`;}
function errorView(copy,retry='retry-route'){return`<div class="error-state" role="alert"><strong>暂时没有连接上</strong><p>${esc(copy)}</p><button class="button secondary small" data-action="${retry}">${icon('refresh')}重新加载</button></div>`;}
function authGate(title='先登录，开启你的校园小集市'){return`<section class="auth-gate"><span class="empty-emoji">🍊</span><span class="eyebrow">YOUR CAMPUS CORNER</span><h1>${title}</h1><p>学校邮箱验证登录后可发布、收藏和站内私信，访客仅可浏览公开商品。</p>${loginLink()}<small>学校邮箱验证仅确认邮箱控制权，不等于在读学籍认证。</small><a class="text-button" href="#/">先逛逛公开好物 ${icon('arrow')}</a></section>`;}
function header(){return`<a class="skip-link" href="#main-content">跳到主要内容</a><div class="demo-strip live-strip"><span>${icon('sun')}一点闲置，一点新的可能。</span><span>西交利物浦大学 · SIP / 太仓 <span class="demo-dot"></span> 闲置好物，共享发现</span></div><header class="site-header"><div class="container header-inner"><a class="brand" href="#/" aria-label="橘子集首页"><img src="/assets/orange.svg" width="42" height="42" alt=""><span>橘子集<small>JUZI CAMPUS</small></span></a><button class="location-button" data-action="campus">${icon('pin')}<span>西交利物浦大学<small>${esc(state.filters.campus||'全部校区')}</small></span>${icon('down')}</button><form class="search-form" role="search"><label class="sr-only" for="global-search">搜索校园闲置</label>${icon('search')}<input id="global-search" name="query" placeholder="搜搜好物，让心动有回音" value="${esc(state.filters.query)}" autocomplete="off"><button type="submit">搜索</button></form><div class="header-actions"><a class="header-favorite" href="#/profile?tab=favorites">${icon('heart')}<span>我的收藏</span></a><a class="button primary" href="#/publish">${icon('plus')}<span>发布闲置</span></a><a class="header-avatar" href="#/profile" aria-label="${signedIn()?'个人中心':'登录与个人中心'}">🍊</a></div></div></header>`;}
function footer(){return`<footer class="site-footer container"><div><a class="brand" href="#/"><img src="/assets/orange.svg" alt="" width="32" height="32"><span>橘子集</span></a><p>让每一件好物，都有下一段校园故事。</p></div><div class="footer-links"><span>校园发现 · 友好面交 · 循环生活</span><button class="text-button" data-action="about">关于橘子集</button><button class="text-button" data-action="privacy">隐私与联系</button>${signedIn()?'<a href="#/settings">设置</a>':`<a href="${esc(loginPath())}">登录</a>`}</div><p class="footer-note">商品与照片公开展示，联系方式仅在双方同意交换后可见。学校邮箱验证不等于在读学籍核验；面交前请自行核实。</p></footer>`;}
function mobileNav(path){const profile=path==='/profile',publish=path==='/publish',messages=path.startsWith('/messages');return`<nav class="mobile-nav" aria-label="手机导航"><a href="#/" class="${path==='/'?'active':''}">${icon('home')}<span>逛一逛</span></a><a href="#/profile?tab=favorites" class="${profile&&state.tab==='favorites'?'active':''}">${icon('heart')}<span>收藏</span></a><a href="#/publish" class="mobile-publish ${publish?'active':''}">${icon('plus')}<span>发布</span></a><a href="#/messages" class="${messages?'active':''}">${icon('message')}<span>消息</span></a><a href="#/profile" class="${(profile&&state.tab!=='favorites')||path==='/settings'?'active':''}">${icon('user')}<span>我的</span></a></nav>`;}
